-- queries/admin_stats_24h.sql
-- Source: loop/admin_views.py:136-148 (Count target_count/completed/failed/skipped).
-- Executed SQL for one detail GET; TurnStatus from assistant/models.py:64-70.
SELECT "instances"."created_at", "instances"."updated_at", "instances"."created_by_id", "instances"."updated_by_id", "instances"."deleted_at", "instances"."id", "instances"."instance_name", "instances"."whitelist_emails", "instances"."instance_id", "instances"."current_version", "instances"."latest_version", "instances"."edition", "instances"."domain", "instances"."last_checked_at", "instances"."namespace", "instances"."is_telemetry_enabled", "instances"."is_support_required", "instances"."is_setup_done", "instances"."is_signup_screen_visited", "instances"."is_verified", "instances"."is_test", "instances"."is_current_version_deprecated" FROM "instances" WHERE "instances"."deleted_at" IS NULL ORDER BY "instances"."created_at" DESC LIMIT 1
SELECT 1 AS "a" FROM "instance_admins" WHERE ("instance_admins"."deleted_at" IS NULL AND "instance_admins"."instance_id" = 'b9d158b429ce4bad8306f0d206de4306'::uuid AND "instance_admins"."role" >= 15 AND "instance_admins"."user_id" = '45690c4670304b4fa792d3eba02dd6b7'::uuid) LIMIT 1
SELECT "loop_jobs"."created_at", "loop_jobs"."updated_at", "loop_jobs"."created_by_id", "loop_jobs"."updated_by_id", "loop_jobs"."deleted_at", "loop_jobs"."id", "loop_jobs"."slug", "loop_jobs"."name", "loop_jobs"."public_name", "loop_jobs"."public_description", "loop_jobs"."prompt", "loop_jobs"."min_role", "loop_jobs"."enabled", "loop_jobs"."is_builtin", "loop_jobs"."dtstart", "loop_jobs"."rrule", "loop_jobs"."tzid" FROM "loop_jobs" WHERE ("loop_jobs"."deleted_at" IS NULL AND "loop_jobs"."deleted_at" IS NULL AND "loop_jobs"."id" = '42be11bb067b495c86d9bd53926d4026'::uuid) ORDER BY "loop_jobs"."created_at" DESC LIMIT 1
SELECT COUNT("loop_targets"."id") AS "target_count", COUNT("loop_targets"."last_run_id") FILTER (WHERE ("assistant_turn"."completed_at" >= '2026-09-27 04:28:09.690683+00:00'::timestamptz AND "assistant_turn"."status" = 'completed')) AS "completed", COUNT("loop_targets"."last_run_id") FILTER (WHERE ("assistant_turn"."completed_at" >= '2026-09-27 04:28:09.690683+00:00'::timestamptz AND "assistant_turn"."status" = 'failed')) AS "failed", COUNT("loop_targets"."id") FILTER (WHERE "loop_targets"."last_skipped_at" >= '2026-09-27 04:28:09.690683+00:00'::timestamptz) AS "skipped" FROM "loop_targets" LEFT OUTER JOIN "assistant_turn" ON ("loop_targets"."last_run_id" = "assistant_turn"."id") WHERE ("loop_targets"."deleted_at" IS NULL AND "loop_targets"."deleted_at" IS NULL AND "loop_targets"."job_id" = '42be11bb067b495c86d9bd53926d4026'::uuid)
